<?php

use PHPUnit\Framework\TestCase;

/**
 * Promotes captured MySQL server corpus failures to explicit SQLite translator
 * regression cases.
 *
 * @group mysql-core-failures
 */
class WP_MySQL_Core_SQLite_Failure_Tests extends TestCase {
	// Captured from a full MySQL server corpus replay against the SQLite backend.
	// phpcs:ignore Generic.Files.LineLength.TooLong
	const FAILURE_QUERY_PAYLOAD = '';

	private $engine;
	private $sqlite;

	public static function setUpBeforeClass(): void {
		if ( ! defined( 'FQDB' ) ) {
			define( 'FQDB', ':memory:' );
			define( 'FQDBDIR', __DIR__ . '/../testdb' );
		}
		error_reporting( E_ALL & ~E_DEPRECATED );
		if ( ! isset( $GLOBALS['table_prefix'] ) ) {
			$GLOBALS['table_prefix'] = 'wptests_';
		}
		if ( ! isset( $GLOBALS['wpdb'] ) ) {
			$GLOBALS['wpdb']                  = new stdClass();
			$GLOBALS['wpdb']->suppress_errors = false;
			$GLOBALS['wpdb']->show_errors     = true;
		}
	}

	public function setUp(): void {
		$this->sqlite = new PDO( 'sqlite::memory:' );
		$this->engine = new WP_SQLite_Translator( $this->sqlite );
	}

	public function test_captured_mysql_core_failure_rows_are_required_to_pass(): void {
		$failures = array();
		$queries  = $this->failure_queries();

		foreach ( $queries as $row => $query ) {
			try {
				$result = $this->engine->query( $query );
				if ( false !== $result && '' === $this->engine->get_error_message() ) {
					continue;
				}

				$error = $this->engine->get_error_message();
			} catch ( Throwable $e ) {
				$error = get_class( $e ) . ': ' . $e->getMessage();
			}

			$failures[] = sprintf(
				'row %d: %s :: %s',
				$row,
				$this->preview_error( $error ),
				$this->preview_query( $query )
			);
		}

		$this->assertSame( 1094, count( $queries ), 'The embedded MySQL corpus failure list should be complete.' );

		if ( count( $failures ) > 0 ) {
			$this->fail(
				sprintf(
					"%d captured MySQL core rows still fail:\n%s",
					count( $failures ),
					implode( "\n", array_slice( $failures, 0, 150 ) )
				)
			);
		}
	}

	private function failure_queries(): array {
		$decoded = base64_decode( self::FAILURE_QUERY_PAYLOAD, true );
		$this->assertNotFalse( $decoded, 'The embedded MySQL corpus payload should be valid base64.' );

		$json = gzinflate( $decoded );
		$this->assertNotFalse( $json, 'The embedded MySQL corpus payload should inflate.' );

		$queries = json_decode( $json, true );
		$this->assertIsArray( $queries, 'The embedded MySQL corpus payload should decode to row-indexed queries.' );

		return $queries;
	}

	private function preview_query( string $query ): string {
		$query = preg_replace( '/\s+/', ' ', trim( $query ) );
		if ( strlen( $query ) <= 120 ) {
			return $query;
		}

		return substr( $query, 0, 117 ) . '...';
	}

	private function preview_error( string $error ): string {
		if ( preg_match( '/Error message was:\s*(.*?)<\/div>/s', $error, $matches ) ) {
			$error = $matches[1];
		}

		$error = html_entity_decode( strip_tags( $error ), ENT_QUOTES );
		$error = str_replace( "\xc2\xa0", ' ', $error );
		$error = preg_replace( '/\s+/', ' ', trim( $error ) );
		if ( strlen( $error ) <= 160 ) {
			return $error;
		}

		return substr( $error, 0, 157 ) . '...';
	}
}
